// ELF parsing
function loadELF(filename) {
  const buf = fs.readFileSync(filename);
  // Parse ELF header
  const e_entry = buf.readUInt32LE(24);
  const e_phoff = buf.readUInt32LE(28);
  const e_phentsize = buf.readUInt16LE(42);
  const e_phnum = buf.readUInt16LE(44);

  const segments = [];
  for (let i = 0; i < e_phnum; i++) {
    const off = e_phoff + i * e_phentsize;
    const p_type = buf.readUInt32LE(off);
    if (p_type !== 1) continue; // PT_LOAD
    const p_offset = buf.readUInt32LE(off + 4);
    const p_vaddr = buf.readUInt32LE(off + 8);
    const p_filesz = buf.readUInt32LE(off + 16);
    const p_memsz = buf.readUInt32LE(off + 20);
    segments.push({ offset: p_offset, vaddr: p_vaddr, filesz: p_filesz, memsz: p_memsz, data: buf.slice(p_offset, p_offset + p_filesz) });
  }
  return { entry: e_entry, segments };
}

// Memory - paged
const PAGE_SIZE = 4096;
class Memory {
  constructor() {
    this.pages = new Array(0x80000000 / PAGE_SIZE);
  }

  _getPage(addr) {
    const pn = addr >>> 12;
    let p = this.pages[pn];
    if (!p) {
      p = new Uint8Array(PAGE_SIZE);
      this.pages[pn] = p;
    }
    return p;
  }

  read8(addr) {
    addr = addr >>> 0;
    const p = this.pages[addr >>> 12];
    if (!p) return 0;
    return p[addr & 0xfff];
  }

  write8(addr, val) {
    addr = addr >>> 0;
    const p = this._getPage(addr);
    p[addr & 0xfff] = val & 0xff;
  }

  read32(addr) {
    // Handle page boundary
    const off = addr & 0xfff;
    if (off <= PAGE_SIZE - 4) {
      const p = this.pages[addr >>> 12];
      if (!p) return 0;
      return p[off] | (p[off+1] << 8) | (p[off+2] << 16) | (p[off+3] << 24);
    }
    return this.read8(addr) | (this.read8(addr+1) << 8) | (this.read8(addr+2) << 16) | (this.read8(addr+3) << 24);
  }

